        ("Past", "\u0388\u03bc\u03b1\u03b8\u03b1 \u03b5\u03bb\u03bb\u03b7\u03bd\u03b9\u03ba\u03ac.", "\u00c9matha elinik\u00e1.", "I learned Greek."),
        ("Future", "\u0398\u03b1 \u03bc\u03ac\u03b8\u03c9 \u03b5\u03bb\u03bb\u03b7\u03bd\u03b9\u03ba\u03ac.", "Tha m\u00e1tho elinik\u00e1.", "I will learn Greek."),
